# 文件职责：提供无外部资源的本机任务页面，用户文本只经textContent展示。
PAGE = r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>Autodidact · 本机任务</title>
<style>
:root{font-family:Segoe UI,Microsoft YaHei,sans-serif;color:#203145;background:#f3f6fa}*{box-sizing:border-box}body{margin:0}header{background:#17283c;color:white;padding:20px 28px;display:flex;justify-content:space-between;align-items:center}header h1{font-size:21px;margin:0 0 6px}header p{font-size:13px;margin:0;color:#bdcce0}main{display:grid;grid-template-columns:300px minmax(360px,1fr) 340px;gap:18px;padding:22px;max-width:1700px;margin:auto}.card{background:white;border:1px solid #e0e7ef;border-radius:12px;padding:18px;margin-bottom:16px}h2{font-size:16px;margin:0 0 15px}h3{font-size:14px}input,textarea,select{font:inherit;width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:6px;margin:5px 0 12px;background:white}textarea{resize:vertical}label,.muted{font-size:12px;color:#61728a;line-height:1.7}button{cursor:pointer;border:1px solid #ccd6e3;border-radius:6px;padding:9px 13px;background:white;color:#24384e;margin:3px 5px 3px 0;font:inherit;font-size:13px}button.primary{background:#2463d4;color:white;border-color:#2463d4}button.danger{color:#a22734}button:disabled{opacity:.45;cursor:default}.row{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.pill{background:#e9f0ff;color:#2457a9;border-radius:20px;padding:6px 12px;font-size:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.65 Consolas,monospace;max-height:390px;overflow:auto;background:#f5f7fb;padding:12px;border-radius:7px}.event{padding:12px 0;border-bottom:1px solid #e5eaf1}.event summary{font-size:13px;cursor:pointer}.task{display:block;width:100%;text-align:left;overflow-wrap:anywhere;padding:12px}.task.selected{background:#edf3ff;border-color:#88a9e9}.notice{background:#fff8e6;border:1px solid #f0dca8;padding:12px;border-radius:7px;font-size:12px;line-height:1.7}.error{color:#b02032}.empty{padding:35px 10px;color:#76849a;text-align:center}#pending{border-color:#d9b55b}#status-message{font-size:13px;min-height:20px}#task-title{overflow-wrap:anywhere}@media(max-width:1150px){main{grid-template-columns:270px 1fr}.tools{grid-column:1/-1}}@media(max-width:700px){main{display:block;padding:12px}header{padding:16px}}
</style><header><div><h1>Autodidact <span style="font-weight:400">/ 本机任务</span></h1><p>在选定项目里执行，逐项确认修改，保留过程与结果。</p></div><span class="pill" id="device">连接本机…</span></header>
<main><aside><section class="card"><h2>创建任务</h2><label for="workspace">项目目录</label><input id="workspace" placeholder="E:\project\your-project"><label for="objective">希望完成什么</label><textarea id="objective" rows="4" placeholder="例如：检查一个Python文件，修改后运行语法检查。"></textarea><label for="mode">执行方式</label><select id="mode"><option value="manual">手动工具 · 无模型调用</option value="agent">模型规划 · 按步骤执行</option></select><p class="muted" id="model-info"></p><button class="primary" id="create">创建任务</button><p class="muted">模型模式的开始/继续会将目标及所读内容发送给你配置的模型。写入与命令始终逐项确认。</p></section><section class="card"><h2>最近任务</h2><div id="tasks"></div></section></aside>
<section><div class="card"><div class="row" style="justify-content:space-between"><h2 id="task-title">开始一个本机任务</h2><span id="task-state" class="pill">待选择</span></div><p id="task-root" class="muted"></p><div class="row"><button class="primary" id="advance" disabled>开始 / 继续规划</button><button class="danger" id="stop" disabled>暂停任务</button><button id="complete" disabled>已审阅，关闭任务</button></div><p id="status-message" role="status"></p><p class="muted" id="usage"></p></div>
<div id="pending" class="card" hidden><h2>等待你确认的步骤</h2><p class="notice">请检查完整参数和文件差异。测试命令会运行项目代码，具有当前用户权限；请只对你信任的项目执行。</p><pre id="proposal"></pre><button class="primary" id="approve">确认执行这一步</button><button id="reject">拒绝，重新规划</button></div>
<div class="card"><h2>执行记录</h2><div id="events"><p class="empty">创建任务后，读取内容、差异、命令输出和结果会显示在这里。</p></div></div></section>
<aside class="tools"><section class="card"><h2>本地工具</h2><label for="tool">操作</label><select id="tool"><option value="list">列出文件</option><option value="read">读取文本</option><option value="write">预览文件写入</option><option value="command">预览命令</option><option value="finish">记录总结</option></select><label for="path">相对项目路径</label><input id="path" value="." placeholder="例如 src/example.py"><label for="sha">已有文件的读取摘要</label><input id="sha" placeholder="读取文件后自动填入"><label for="content">完整新内容 / 总结</label><textarea id="content" rows="7"></textarea><label for="command">命令类型</label><select id="command"><option value="git_status">Git 状态</option><option value="git_diff">Git 差异</option><option value="python_check">Python 语法检查</option><option value="pytest">pytest 测试（执行项目代码）</option></select><label for="paths">命令目标（每行一个相对路径）</label><textarea id="paths" rows="2" placeholder="例如 tests/test_example.py"></textarea><button id="propose" disabled>提交工具步骤</button></section><div class="notice">任务日志保存在本机，与研究知识库分开。命令成功或模型总结不会自动提升信念。暂停保留已经完成的文件修改；重启后不会自动执行历史任务。</div></aside></main>
<script nonce="NONCE">
const token='TOKEN', $=id=>document.getElementById(id);
let selected=null,current=null,lastRender='',pendingDigest=null;
const labels={ready:'待执行',planning:'模型规划中',executing:'正在执行',awaiting_approval:'待确认',paused:'已暂停',interrupted:'上次运行中断',failed:'步骤失败',review:'等待审阅',completed:'已关闭'};
const tools={list:'列出文件',read:'读取文本',write:'写入文件',command:'运行命令',finish:'总结'};
const commands={git_status:'Git 状态',git_diff:'Git 差异',python_check:'Python 语法检查',pytest:'pytest 测试'};
const kinds={created:'创建任务',proposal:'待确认步骤',approved:'用户已确认',result:'执行结果',read:'读取文件',list:'项目文件',model:'模型提议',summary:'任务总结',error:'步骤错误',paused:'暂停',interrupted:'中断记录',rejected:'用户已拒绝',reviewed:'已审阅',budget:'用量限制'};
function proposalText(p){const r=p.request,v=p.preview;if(r.tool==='write')return `文件：${r.path}\n操作：${v.creates_file?'创建新文件':'替换已有文件'}\n原版本：${v.before_sha256||'不存在'}\n新版本：${v.after_sha256}\n\n修改差异：\n${v.diff}\n\n待写入的完整内容：\n${r.content}`;return `命令：${commands[r.command]}\n目标：${r.paths.length?r.paths.join('\n'):'整个项目'}\n执行程序：${v.argv[0]}\n超时：${r.timeout} 秒\n${r.command==='pytest'?'注意：会执行项目代码，具有当前用户权限。':'此命令用于查看或检查所选项目。'}`;}
function eventText(e){const d=e.data;if(e.kind==='proposal')return proposalText(d);if(e.kind==='read')return `文件：${d.path}\n读取摘要：${d.sha256}\n\n${d.content}`;if(e.kind==='list')return d.files.join('\n')+(d.truncated?'\n（文件列表已截断）':'');if(e.kind==='result'){const r=d.result;if(d.tool==='command')return `命令：${commands[r.command]}\n结果：${r.passed?'通过':'未通过'}\n退出码：${r.exit_code}\n${r.timed_out?'已超时并停止进程树。\n':''}${r.output_truncated?'输出过长，已截断保存。\n':''}\n${r.output}`;return `文件已写入：${r.path}\n新版本：${r.after_sha256}\n\n${r.diff}`;}if(e.kind==='model')return `模型：${d.provider} / ${d.model}\n下一步：${tools[d.request.tool]}\n${d.request.message||''}`;return d.message||d.note||(e.kind==='approved'?'用户确认了所展示的这一步。':JSON.stringify(d,null,2));}
async function api(path,data){const r=await fetch('/api/local'+path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Autodidact-Token':token},body:data===undefined?undefined:JSON.stringify(data)});const v=await r.json();if(!r.ok)throw Error(v.error||'请求失败');return v;}
function message(text,bad=false){$('status-message').textContent=text;$('status-message').className=bad?'error':'';}
async function perform(action){try{await action();await refresh();}catch(e){message(e.message,true);}}
function render(task){current=task;$('task-title').textContent=task.objective;$('task-root').textContent=task.workspace;$('task-state').textContent=labels[task.status]||task.status;$('usage').textContent=`模型调用 ${task.model_calls}/${task.max_calls} · 工具步骤 ${task.steps}/40 · 日配额按 UTC 计算`;
const busy=['planning','executing','awaiting_approval','completed'].includes(task.status);$('advance').disabled=busy||task.mode!=='agent';$('propose').disabled=busy;$('complete').disabled=busy;$('stop').disabled=task.status==='completed';
pendingDigest=task.pending?.digest||null;$('pending').hidden=!task.pending;
if(task.pending){$('proposal').textContent=proposalText(task.pending);}
const signature=task.id+':'+task.updated;if(lastRender===signature)return;lastRender=signature;
const events=$('events');events.replaceChildren();for(const e of task.events){const d=document.createElement('details');d.className='event';const s=document.createElement('summary');s.textContent=`${e.sequence}. ${kinds[e.kind]||e.kind} · ${new Date(e.at).toLocaleTimeString()}`;d.append(s);const p=document.createElement('pre');p.textContent=eventText(e);d.append(p);const raw=document.createElement('details'),label=document.createElement('summary'),data=document.createElement('pre');label.textContent='查看完整原始记录';data.textContent=JSON.stringify(e.data,null,2);raw.append(label,data);d.append(raw);d.open=e.sequence===task.events.length;events.append(d);}
}
async function refresh(){const v=await api('/tasks');const list=$('tasks');list.replaceChildren();for(const t of v.tasks){const b=document.createElement('button');b.className='task'+(selected===t.id?' selected':'');b.textContent=(labels[t.status]||t.status)+' · '+t.objective;b.onclick=()=>perform(async()=>{selected=t.id;lastRender='';message('');render(await api('/tasks/'+selected));});list.append(b);}if(selected)render(await api('/tasks/'+selected));}
$('create').onclick=()=>perform(async()=>{const t=await api('/tasks',{workspace:$('workspace').value,objective:$('objective').value,mode:$('mode').value});selected=t.id;lastRender='';message('任务已创建。选择工具，或开始模型规划。');render(t);});
$('propose').onclick=()=>perform(async()=>{const tool=$('tool').value;const r={tool,path:$('path').value||'.',content:$('content').value,expected_sha256:$('sha').value||null,command:$('command').value,paths:$('paths').value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean),message:tool==='finish'?$('content').value:''};const t=await api('/tasks/'+selected+'/propose',r);const e=t.events.at(-1);if(e?.kind==='read'){$('sha').value=e.data.sha256;$('content').value=e.data.content;}render(t);message(t.pending?'请核对待确认步骤。':'工具步骤已记录。');});
$('advance').onclick=()=>perform(async()=>{await api('/tasks/'+selected+'/advance',{});message('正在规划；遇到写入或命令会等待确认。');});
$('approve').onclick=()=>perform(async()=>{await api('/tasks/'+selected+'/approve',{digest:pendingDigest});message('已确认；执行结果将保存在记录中。');});
$('reject').onclick=()=>perform(async()=>{render(await api('/tasks/'+selected+'/reject',{}));message('已拒绝该步骤。');});
$('stop').onclick=()=>perform(async()=>{render(await api('/tasks/'+selected+'/stop',{}));message('已暂停；已经完成的修改仍保留。');});
$('complete').onclick=()=>perform(async()=>{render(await api('/tasks/'+selected+'/complete',{}));message('已审阅并关闭任务。');});
async function init(){try{const v=await api('/info');$('workspace').value=v.workspace;$('device').textContent='执行设备：'+v.device;$('model-info').textContent='配置模型：'+v.provider+(v.model?' / '+v.model:'')+'。Mock 模式请使用手动工具。';await refresh();}catch(e){message(e.message,true);}}
init();setInterval(()=>refresh().catch(e=>message(e.message,true)),2500);
</script></html>'''
